// v16.xx, HIS NOTE (2026-10-09): "the shotgun and any single shot gun like the whisper, meridian lance etc need to deal more damage to be
// competitive against the automatics like the auto rifle and smg". Sustained damage with reloads was about 107 a second for the Auto
// Rifle and 85 to 99 for the SMG and the Support MG, against 45 to 70 for the single shots and 24 for the Whisper. Per shot now: Scav
// Pistol 23, Tacker 20, Scuttle 12 a pellet, Magnum 62, Marksman Rifle 64, Longshot 170, Meridian Lance 150, Riot Scattergun 16 a pellet,
// Whisper 24 and a shot every 0.40 s. The single shots land about 70 to 110 a second sustained; they still trade the magazine for reach and
// the hit that ends a fight. The Burst Carbine (three a pull, about 85) is unchanged.
var WTIER={

check:
{v:'VER',what:'his note: the single shot guns hit harder, so they keep up with the automatics',
 run:function(){
   var want={pistol:23,tacker:20,scuttle:12,magnum:62,dmr:64,sniper:170,lance:150,shotgun:16,whisper:24}, bad=[], k;
   for(k in want) if(!WEAPONS[k]||WEAPONS[k].dmg!==want[k]) bad.push(k+' does '+(WEAPONS[k]&&WEAPONS[k].dmg)+', not '+want[k]);
   if(WEAPONS.whisper&&WEAPONS.whisper.rof!==400) bad.push('the Whisper fires every '+WEAPONS.whisper.rof+' ms, not 400');
   function sus(w){ var per=w.dmg*(w.pellets||1)*(w.burst||1), shots=w.mag/(w.burst||1); return per*shots/(shots*w.rof/1000+w.reload/1000); }
   var ar=sus(WEAPONS.rifle);
   ['shotgun','lance','dmr','magnum','sniper'].forEach(function(k2){ var s=sus(WEAPONS[k2]); if(s<ar*0.6) bad.push(WEAPONS[k2].name+' sustains '+Math.round(s)+' a second against '+Math.round(ar)+' for the Auto Rifle'); });
   return bad.length?bad.join('; '):null; }},
